1	package reconcore
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service implements the ReconCore contract on top of a Store. The functional
11	// currency is fixed for the lifetime of the process and is the unit every
12	// journal is balanced in.
13	type Service struct {
14		store              *Store
15		functionalCurrency string
16		clock              func() time.Time
17	}
18	
19	// NewService wires a store, a functional currency and an injectable clock.
20	func NewService(store *Store, functionalCurrency string, clock func() time.Time) (*Service, error) {
21		if store == nil {
22			return nil, InternalError("service requires a store")
23		}
24		code, err := validateCurrency(functionalCurrency, "functional currency", true)
25		if err != nil {
26			return nil, err
27		}
28		if clock == nil {
29			clock = time.Now
30		}
31		return &Service{store: store, functionalCurrency: code, clock: clock}, nil
32	}
33	
34	// FunctionalCurrency reports the reporting currency of this process.
35	func (s *Service) FunctionalCurrency() string { return s.functionalCurrency }
36	
37	func (s *Service) now() string {
38		return s.clock().UTC().Format("2006-01-02T15:04:05Z")
39	}
40	
41	// runIdempotent executes action at most once per key. The first response is
42	// stored and replayed for every later request that carries the same key.
43	func (s *Service) runIdempotent(key, operation string, action func(state *State) (any, error)) (any, error) {
44		if key == "" {
45			return nil, ValidationError("Idempotency-Key header is required")
46		}
47		if len(key) > 200 {
48			return nil, ValidationError("Idempotency-Key must be at most 200 characters")
49		}
50		var response any
51		err := s.store.Update(func(state *State) error {
52			if record, found := state.Idempotency[key]; found {
53				if record.Operation != operation {
54					return ConflictError("idempotency key was already used for another operation")
55				}
56				stored, err := decodeResponse(record.Response)
57				if err != nil {
58					return err
59				}
60				response = stored
61				return nil
62			}
63			value, err := action(state)
64			if err != nil {
65				return err
66			}
67			normalized, err := normalizeResponse(value)
68			if err != nil {
69				return err
70			}
71			encoded, err := encodeResponse(normalized)
72			if err != nil {
73				return err
74			}
75			state.Idempotency[key] = &IdempotencyRecord{
76				Key:       key,
77				Operation: operation,
78				Response:  encoded,
79				CreatedAt: s.now(),
80			}
81			response = normalized
82			return nil
83		})
84		if err != nil {
85			return nil, err
86		}
87		return response, nil
88	}
89	
90	type createAccountRequest struct {
91		ID       string  `json:"id"`
92		Name     string  `json:"name"`
93		Type     string  `json:"type"`
94		ParentID *string `json:"parent_id"`
95		Currency string  `json:"currency"`
96	}
97	
98	// CreateAccount adds one node to the chart of accounts.
99	func (s *Service) CreateAccount(body []byte, key string) (any, error) {
100		var request createAccountRequest
101		if err := decodeObject(body, &request); err != nil {
102			return nil, err
103		}
104		id, err := validateIdentifier(request.ID, "account id")
105		if err != nil {
106			return nil, err
107		}
108		name, err := validateText(request.Name, "name")
109		if err != nil {
110			return nil, err
111		}
112		if name == "" {
113			return nil, ValidationError("name is required")
114		}
115		normalBalance, known := normalBalanceByType[request.Type]
116		if !known {
117			return nil, ValidationError("type must be one of asset, liability, equity, revenue or expense")
118		}
119		currency, err := validateCurrency(request.Currency, "currency", true)
120		if err != nil {
121			return nil, err
122		}
123		var parentID *string
124		if request.ParentID != nil {
125			value, err := validateIdentifier(*request.ParentID, "parent_id")
126			if err != nil {
127				return nil, err
128			}
129			parentID = &value
130		}
131		return s.runIdempotent(key, "create-account:"+id, func(state *State) (any, error) {
132			if _, found := state.Accounts[id]; found {
133				return nil, ConflictError("account %s already exists", id)
134			}
135			if parentID != nil {
136				if _, found := state.Accounts[*parentID]; !found {
137					return nil, ValidationError("parent_id %s does not exist", *parentID)
138				}
139			}
140			account := &Account{
141				ID:            id,
142				Name:          name,
143				Type:          request.Type,
144				ParentID:      parentID,
145				Currency:      currency,
146				NormalBalance: normalBalance,
147				CreatedAt:     s.now(),
148			}
149			state.Accounts[id] = account
150			return account, nil
151		})
152	}
153	
154	// ListAccounts returns the whole chart of accounts as a forest.
155	func (s *Service) ListAccounts() (any, error) {
156		return s.store.View(func(state *State) (any, error) {
157			_, roots := accountTree(state)
158			return map[string]any{"accounts": roots}, nil
159		})
160	}
161	
162	// GetAccount returns one account with its subtree.
163	func (s *Service) GetAccount(id string) (any, error) {
164		return s.store.View(func(state *State) (any, error) {
165			nodes, _ := accountTree(state)
166			node, found := nodes[id]
167			if !found {
168				return nil, NotFoundError("account %s was not found", id)
169			}
170			return node, nil
171		})
172	}
173	
174	// GetBalance derives the account balance at asOf from the journals only.
175	func (s *Service) GetBalance(id, asOf string) (any, error) {
176		if id == "" {
177			return nil, ValidationError("account id is required")
178		}
179		if asOf == "" {
180			return nil, ValidationError("as_of query parameter is required")
181		}
182		date, err := validateDate(asOf, "as_of")
183		if err != nil {
184			return nil, err
185		}
186		return s.store.View(func(state *State) (any, error) {
187			account, found := state.Accounts[id]
188			if !found {
189				return nil, NotFoundError("account %s was not found", id)
190			}
191			return s.computeBalance(state, account, date), nil
192		})
193	}
194	
195	func (s *Service) computeBalance(state *State, account *Account, asOf string) *Balance {
196		balance := &Balance{
197			AccountID:          account.ID,
198			AccountName:        account.Name,
199			AccountType:        account.Type,
200			NormalBalance:      account.NormalBalance,
201			Currency:           account.Currency,
202			FunctionalCurrency: s.functionalCurrency,
203			AsOf:               asOf,
204		}
205		for _, journal := range sortedJournals(state) {
206			if journal.Date > asOf {
207				continue
208			}
209			for _, line := range journal.Lines {
210				if line.AccountID != account.ID {
211					continue
212				}
213				balance.PostingCount++
214				if line.Side == "debit" {
215					balance.DebitMinor += line.AmountMinor
216					balance.FunctionalDebitMinor += line.FunctionalAmountMinor
217				} else {
218					balance.CreditMinor += line.AmountMinor
219					balance.FunctionalCreditMinor += line.FunctionalAmountMinor
220				}
221				if balance.FirstPostingDate == "" || journal.Date < balance.FirstPostingDate {
222					balance.FirstPostingDate = journal.Date
223				}
224				if journal.Date > balance.LastPostingDate {
225					balance.LastPostingDate = journal.Date
226				}
227			}
228		}
229		balance.NetMinor = balance.DebitMinor - balance.CreditMinor
230		balance.FunctionalNetMinor = balance.FunctionalDebitMinor - balance.FunctionalCreditMinor
231		balance.BalanceMinor = balance.NetMinor
232		if account.NormalBalance == "credit" {
233			balance.BalanceMinor = -balance.NetMinor
234		}
235		return balance
236	}
237	
238	// GetTrialBalance derives a read-only trial balance at asOf from the stored
239	// accounts and immutable journals. It never writes state and is recomputed
240	// from the current ledgers on every call.
241	func (s *Service) GetTrialBalance(asOf string) (any, error) {
242		if asOf == "" {
243			return nil, ValidationError("as_of query parameter is required")
244		}
245		date, err := validateDate(asOf, "as_of")
246		if err != nil {
247			return nil, err
248		}
249		return s.store.View(func(state *State) (any, error) {
250			rows := make(map[string]*TrialBalanceRow, len(state.Accounts))
251			ordered := make([]*TrialBalanceRow, 0, len(state.Accounts))
252			for _, account := range sortedAccounts(state) {
253				row := &TrialBalanceRow{
254					AccountID:   account.ID,
255					AccountName: account.Name,
256					Currency:    account.Currency,
257				}
258				rows[account.ID] = row
259				ordered = append(ordered, row)
260			}
261			for _, journal := range sortedJournals(state) {
262				if journal.Date > date {
263					continue
264				}
265				for _, line := range journal.Lines {
266					row := rows[line.AccountID]
267					if row == nil {
268						return nil, InternalError("journal %s posts to unknown account %s", journal.ID, line.AccountID)
269					}
270					row.PostingCount++
271					if line.Side == "debit" {
272						row.DebitMinor += line.AmountMinor
273						row.FunctionalDebitMinor += line.FunctionalAmountMinor
274					} else {
275						row.CreditMinor += line.AmountMinor
276						row.FunctionalCreditMinor += line.FunctionalAmountMinor
277					}
278				}
279			}
280			report := &TrialBalance{
281				AsOf:               date,
282				FunctionalCurrency: s.functionalCurrency,
283				Accounts:           ordered,
284			}
285			for _, row := range ordered {
286				row.NetMinor = row.DebitMinor - row.CreditMinor
287				row.FunctionalNetMinor = row.FunctionalDebitMinor - row.FunctionalCreditMinor
288				report.PostingCount += row.PostingCount
289				if row.FunctionalNetMinor >= 0 {
290					report.FunctionalDebitTotalMinor += row.FunctionalNetMinor
291				} else {
292					report.FunctionalCreditTotalMinor += -row.FunctionalNetMinor
293				}
294			}
295			report.Status = "balanced"
296			if report.FunctionalDebitTotalMinor != report.FunctionalCreditTotalMinor {
297				report.Status = "unbalanced"
298			}
299			return report, nil
300		})
301	}
302	
303	// GetFinancialStatements derives a read-only balance sheet at asOf and an
304	// income statement over the closed period [periodStart, periodEnd]. It is
305	// recomputed from the stored functional amounts on the immutable journals on
306	// every call, never writes state, creates no vouchers and changes no close.
307	func (s *Service) GetFinancialStatements(asOf, periodStart, periodEnd string) (any, error) {
308		if asOf == "" {
309			return nil, ValidationError("as_of query parameter is required")
310		}
311		asOfDate, err := validateDate(asOf, "as_of")
312		if err != nil {
313			return nil, err
314		}
315		if periodStart == "" {
316			return nil, ValidationError("period_start query parameter is required")
317		}
318		startDate, err := validateDate(periodStart, "period_start")
319		if err != nil {
320			return nil, err
321		}
322		if periodEnd == "" {
323			return nil, ValidationError("period_end query parameter is required")
324		}
325		endDate, err := validateDate(periodEnd, "period_end")
326		if err != nil {
327			return nil, err
328		}
329		if startDate > endDate {
330			return nil, ValidationError("period_start must not be after period_end")
331		}
332		if endDate > asOfDate {
333			return nil, ValidationError("period_end must not be after as_of")
334		}
335		return s.store.View(func(state *State) (any, error) {
336			accounts := sortedAccounts(state)
337	
338			// Functional debit and credit totals per account for the balance
339			// sheet window (through asOf) and the income window (the period).
340			asOfDebit := make(map[string]int64, len(accounts))
341			asOfCredit := make(map[string]int64, len(accounts))
342			periodDebit := make(map[string]int64, len(accounts))
343			periodCredit := make(map[string]int64, len(accounts))
344			for _, account := range accounts {
345				asOfDebit[account.ID] = 0
346				asOfCredit[account.ID] = 0
347				periodDebit[account.ID] = 0
348				periodCredit[account.ID] = 0
349			}
350			for _, journal := range sortedJournals(state) {
351				if journal.Date > asOfDate {
352					continue
353				}
354				inPeriod := journal.Date >= startDate && journal.Date <= endDate
355				for _, line := range journal.Lines {
356					if _, known := asOfDebit[line.AccountID]; !known {
357						return nil, InternalError("journal %s posts to unknown account %s", journal.ID, line.AccountID)
358					}
359					if line.Side == "debit" {
360						asOfDebit[line.AccountID] += line.FunctionalAmountMinor
361						if inPeriod {
362							periodDebit[line.AccountID] += line.FunctionalAmountMinor
363						}
364					} else {
365						asOfCredit[line.AccountID] += line.FunctionalAmountMinor
366						if inPeriod {
367							periodCredit[line.AccountID] += line.FunctionalAmountMinor
368						}
369					}
370				}
371			}
372	
373			balanceSheet := &BalanceSheet{
374				Assets:      []*FinancialStatementAccount{},
375				Liabilities: []*FinancialStatementAccount{},
376				Equity:      []*FinancialStatementAccount{},
377			}
378			incomeStatement := &IncomeStatement{
379				Revenue:  []*FinancialStatementAccount{},
380				Expenses: []*FinancialStatementAccount{},
381			}
382			for _, account := range accounts {
383				row := &FinancialStatementAccount{
384					AccountID:   account.ID,
385					AccountName: account.Name,
386					ParentID:    account.ParentID,
387					Currency:    account.Currency,
388				}
389				debitNormal := account.NormalBalance == "debit"
390				balance := asOfDebit[account.ID] - asOfCredit[account.ID]
391				if !debitNormal {
392					balance = -balance
393				}
394				row.FunctionalBalanceMinor = balance
395				switch account.Type {
396				case "asset":
397					balanceSheet.Assets = append(balanceSheet.Assets, row)
398					balanceSheet.AssetsTotalMinor += balance
399				case "liability":
400					balanceSheet.Liabilities = append(balanceSheet.Liabilities, row)
401					balanceSheet.LiabilitiesTotalMinor += balance
402				case "equity":
403					balanceSheet.Equity = append(balanceSheet.Equity, row)
404					balanceSheet.EquityTotalMinor += balance
405				case "revenue":
406					incomeStatement.Revenue = append(incomeStatement.Revenue, periodRow(account, periodCredit, periodDebit))
407					incomeStatement.RevenueTotalMinor += periodCredit[account.ID] - periodDebit[account.ID]
408				case "expense":
409					incomeStatement.Expenses = append(incomeStatement.Expenses, periodRow(account, periodDebit, periodCredit))
410					incomeStatement.ExpensesTotalMinor += periodDebit[account.ID] - periodCredit[account.ID]
411				}
412			}
413			incomeStatement.NetIncomeMinor = incomeStatement.RevenueTotalMinor - incomeStatement.ExpensesTotalMinor
414	
415			// Equity through as_of includes the income earned through as_of, so
416			// the accounting equation balances even before the books are closed.
417			var revenueThroughAsOf, expensesThroughAsOf int64
418			for _, account := range accounts {
419				switch account.Type {
420				case "revenue":
421					revenueThroughAsOf += asOfCredit[account.ID] - asOfDebit[account.ID]
422				case "expense":
423					expensesThroughAsOf += asOfDebit[account.ID] - asOfCredit[account.ID]
424				}
425			}
426			balanceSheet.EquityTotalMinor += revenueThroughAsOf - expensesThroughAsOf
427			balanceSheet.BalanceCheckMinor = balanceSheet.AssetsTotalMinor -
428				balanceSheet.LiabilitiesTotalMinor - balanceSheet.EquityTotalMinor
429			balanceSheet.Status = "balanced"
430			if balanceSheet.BalanceCheckMinor != 0 {
431				balanceSheet.Status = "unbalanced"
432			}
433			return &FinancialStatements{
434				AsOf:               asOfDate,
435				PeriodStart:        startDate,
436				PeriodEnd:          endDate,
437				FunctionalCurrency: s.functionalCurrency,
438				BalanceSheet:       balanceSheet,
439				IncomeStatement:    incomeStatement,
440			}, nil
441		})
442	}
443	
444	// periodRow builds the income-statement row for one account from the functional
445	// totals of journals dated inside the report period; positive holds the side
446	// that increases the account type (debits for expenses, credits for revenue)
447	// and negative the opposite side.
448	func periodRow(account *Account, positive, negative map[string]int64) *FinancialStatementAccount {
449		return &FinancialStatementAccount{
450			AccountID:              account.ID,
451			AccountName:            account.Name,
452			ParentID:               account.ParentID,
453			Currency:               account.Currency,
454			FunctionalBalanceMinor: positive[account.ID] - negative[account.ID],
455		}
456	}
