527		ID    string                `json:"id"`
528		Date  string                `json:"date"`
529		Memo  string                `json:"memo"`
530		Lines []*journalLineRequest `json:"lines"`
531	}
532	
533	// CreateJournal posts an immutable voucher once it balances in the functional
534	// currency. A date inside a closed period is rejected.
535	func (s *Service) CreateJournal(body []byte, key string) (any, error) {
536		var request createJournalRequest
537		if err := decodeObject(body, &request); err != nil {
538			return nil, err
539		}
540		id, date, memo, err := validateJournalHead(request.ID, request.Date, request.Memo, len(request.Lines))
541		if err != nil {
542			return nil, err
543		}
544		return s.runIdempotent(key, "create-journal:"+id, func(state *State) (any, error) {
545			if _, found := state.Journals[id]; found {
546				return nil, ConflictError("journal %s already exists", id)
547			}
548			if closedPeriodFor(state, date) != nil {
549				return nil, ConflictError("closed period rejects journal")
550			}
551			journal, err := s.buildJournal(state, &request, id, date, memo)
552			if err != nil {
553				return nil, err
554			}
555			state.Journals[id] = journal
556			return journal, nil
557		})
558	}
559	
560	// validateJournalHead checks the journal fields that do not depend on the
561	// stored state and returns them normalized.
562	func validateJournalHead(rawID, rawDate, rawMemo string, lineCount int) (string, string, string, error) {
563		id, err := validateIdentifier(rawID, "journal id")
564		if err != nil {
565			return "", "", "", err
566		}
567		date, err := validateDate(rawDate, "date")
568		if err != nil {
569			return "", "", "", err
570		}
571		memo, err := validateText(rawMemo, "memo")
572		if err != nil {
573			return "", "", "", err
574		}
575		if lineCount < 2 {
576			return "", "", "", ValidationError("lines must contain at least two postings")
577		}
578		return id, date, memo, nil
579	}
580	
581	// buildJournal resolves every line and freezes the balanced voucher. The
582	// caller owns the duplicate-id and closed-period policy.
583	func (s *Service) buildJournal(state *State, request *createJournalRequest, id, date, memo string) (*Journal, error) {
584		journal := &Journal{
585			ID:                 id,
586			Date:               date,
587			Memo:               memo,
588			FunctionalCurrency: s.functionalCurrency,
589			Lines:              []*JournalLine{},
590			CreatedAt:          s.now(),
591		}
592		var debits, credits int64
593		for position, raw := range request.Lines {
594			line, err := s.buildJournalLine(state, raw, position+1, date)
595			if err != nil {
596				return nil, err
597			}
598			if line.Side == "debit" {
599				debits += line.FunctionalAmountMinor
600			} else {
601				credits += line.FunctionalAmountMinor
602			}
603			journal.Lines = append(journal.Lines, line)
604		}
605		if debits != credits {
606			return nil, ValidationError(
607				"journal is not balanced in %s: debits %d, credits %d",
608				s.functionalCurrency, debits, credits,
609			)
610		}
611		journal.DebitFunctionalMinor = debits
612		journal.CreditFunctionalMinor = credits
613		return journal, nil
614	}
