616	// closedPeriodFor returns the close that covers date, or nil when the date
617	// falls in an open period.
618	func closedPeriodFor(state *State, date string) *PeriodClose {
619		for _, close := range state.PeriodCloses {
620			if close.Period.Start <= date && date <= close.Period.End {
621				return close
622			}
623		}
624		return nil
625	}
