638	type createReversalRequest struct {
639		ID   string `json:"id"`
640		Date string `json:"date"`
641		Memo string `json:"memo"`
642	}
643	
644	// CreateReversal posts exactly one reversal journal for the journal named in
645	// the path. The reversal mirrors every line of the original with debit and
646	// credit swapped, keeps the stored amounts, rate fractions, rate sources and
647	// functional amounts, and never resolves a fresh rate, so the pair cancels
648	// exactly in both the original and the functional currency. The reversal
649	// journal itself is the durable record that the original has been reversed:
650	// both are committed in the same atomic state write, so a restart cannot
651	// allow a second reversal.
652	func (s *Service) CreateReversal(journalID string, body []byte, key string) (any, error) {
653		var request createReversalRequest
654		if err := decodeObject(body, &request); err != nil {
655			return nil, err
656		}
657		id, err := validateIdentifier(request.ID, "journal id")
658		if err != nil {
659			return nil, err
660		}
661		date, err := validateDate(request.Date, "date")
662		if err != nil {
663			return nil, err
664		}
665		memo, err := validateText(request.Memo, "memo")
666		if err != nil {
667			return nil, err
668		}
669		if memo == "" {
670			return nil, ValidationError("memo is required")
671		}
672		return s.runIdempotent(key, "create-reversal:"+journalID+":"+id, func(state *State) (any, error) {
673			original, found := state.Journals[journalID]
674			if !found {
675				return nil, NotFoundError("journal %s was not found", journalID)
676			}
677			if date < original.Date {
678				return nil, ValidationError(
679					"date must not be earlier than the date %s of journal %s",
680					original.Date, journalID,
681				)
682			}
683			if original.ReversalOf != "" {
684				return nil, ConflictError("journal %s is itself a reversal and cannot be reversed", journalID)
685			}
686			for _, journal := range state.Journals {
687				if journal.ReversalOf == journalID {
688					return nil, ConflictError("journal %s was already reversed by %s", journalID, journal.ID)
689				}
690			}
691			if _, found := state.Journals[id]; found {
692				return nil, ConflictError("journal %s already exists", id)
693			}
694			if closedPeriodFor(state, date) != nil {
695				return nil, ConflictError("closed period rejects journal")
696			}
697			reversal := &Journal{
698				ID:                    id,
699				Date:                  date,
700				Memo:                  memo,
701				FunctionalCurrency:    original.FunctionalCurrency,
702				Lines:                 make([]*JournalLine, 0, len(original.Lines)),
703				DebitFunctionalMinor:  original.CreditFunctionalMinor,
704				CreditFunctionalMinor: original.DebitFunctionalMinor,
705				CreatedAt:             s.now(),
706				ReversalOf:            journalID,
707			}
708			for _, line := range original.Lines {
709				side := "debit"
710				if line.Side == "debit" {
711					side = "credit"
712				}
713				reversal.Lines = append(reversal.Lines, &JournalLine{
714					Index:                 line.Index,
715					AccountID:             line.AccountID,
716					Side:                  side,
717					AmountMinor:           line.AmountMinor,
718					Currency:              line.Currency,
719					Rate:                  line.Rate,
720					RateNumerator:         line.RateNumerator,
721					RateDenominator:       line.RateDenominator,
722					RateSource:            line.RateSource,
723					FunctionalAmountMinor: line.FunctionalAmountMinor,
724					Reference:             line.Reference,
725				})
726			}
727			state.Journals[id] = reversal
728			return reversal, nil
729		})
730	}
