732	type createPeriodCloseRequest struct {
733		ID     string        `json:"id"`
734		Period periodRequest `json:"period"`
735	}
736	
737	// CreatePeriodClose freezes one calendar month. The period must be exactly one
738	// natural month and no other close may cover the same month.
739	func (s *Service) CreatePeriodClose(body []byte, key string) (any, error) {
740		var request createPeriodCloseRequest
741		if err := decodeObject(body, &request); err != nil {
742			return nil, err
743		}
744		if _, err := validateIdentifier(request.ID, "period close id"); err != nil {
745			return nil, ValidationError("invalid period close id")
746		}
747		id := request.ID
748		start, err := validatePeriodCloseDate(request.Period.Start)
749		if err != nil {
750			return nil, err
751		}
752		end, err := validatePeriodCloseDate(request.Period.End)
753		if err != nil {
754			return nil, err
755		}
756		if !isCalendarMonth(start, end) {
757			return nil, ValidationError("period is not one calendar month")
758		}
759		return s.runIdempotent(key, "create-period-close:"+id, func(state *State) (any, error) {
760			if _, found := state.PeriodCloses[id]; found {
761				return nil, ConflictError("period close exists")
762			}
763			for _, existing := range state.PeriodCloses {
764				if existing.Period.Start[:7] == start[:7] {
765					return nil, ConflictError("calendar month is closed")
766				}
767			}
768			close := &PeriodClose{
769				ID:                   id,
770				Period:               Period{Start: start, End: end},
771				Status:               "closed",
772				ClosedAt:             s.now(),
773				AdjustmentCount:      0,
774				AdjustmentJournalIDs: []string{},
775			}
776			state.PeriodCloses[id] = close
777			return close, nil
778		})
779	}
780	
781	// validatePeriodCloseDate applies the public YYYY-MM-DD rule under the period
782	// close message.
783	func validatePeriodCloseDate(value string) (string, error) {
784		if _, err := validateDate(value, "period date"); err != nil {
785			return "", ValidationError("invalid period date")
786		}
787		return value, nil
788	}
789	
790	// isCalendarMonth reports whether start and end together span exactly one
791	// natural month, first day to last day.
792	func isCalendarMonth(start, end string) bool {
793		first, err := time.Parse(dateLayout, start)
794		if err != nil || first.Day() != 1 {
795			return false
796		}
797		last, err := time.Parse(dateLayout, end)
798		if err != nil {
799			return false
800		}
801		return last.Equal(first.AddDate(0, 1, -1))
802	}
