978	// CreateStatement imports one bank statement.
979	func (s *Service) CreateStatement(body []byte, key string) (any, error) {
980		var request createStatementRequest
981		if err := decodeObject(body, &request); err != nil {
982			return nil, err
983		}
984		id, err := validateIdentifier(request.ID, "statement id")
985		if err != nil {
986			return nil, err
987		}
988		accountID, err := validateIdentifier(request.AccountID, "account_id")
989		if err != nil {
990			return nil, err
991		}
992		currency, err := validateCurrency(request.Currency, "currency", false)
993		if err != nil {
994			return nil, err
995		}
996		start, err := validateDate(request.Period.Start, "period.start")
997		if err != nil {
998			return nil, err
999		}
1000		end, err := validateDate(request.Period.End, "period.end")
1001		if err != nil {
1002			return nil, err
1003		}
1004		if start > end {
1005			return nil, ValidationError("period.start must not be after period.end")
1006		}
1007		opening, err := validateAmount(request.OpeningBalanceMinor, "opening_balance_minor", true, true)
1008		if err != nil {
1009			return nil, err
1010		}
1011		closing, err := validateAmount(request.ClosingBalanceMinor, "closing_balance_minor", true, true)
1012		if err != nil {
1013			return nil, err
1014		}
1015		return s.runIdempotent(key, "create-statement:"+id, func(state *State) (any, error) {
1016			if _, found := state.Statements[id]; found {
1017				return nil, ConflictError("statement %s already exists", id)
1018			}
1019			account, found := state.Accounts[accountID]
1020			if !found {
1021				return nil, ValidationError("account_id %s does not exist", accountID)
1022			}
1023			if currency == "" {
1024				currency = account.Currency
1025			}
1026			if currency != account.Currency {
1027				return nil, ValidationError(
1028					"currency %s must match the currency %s of account %s",
1029					currency, account.Currency, accountID,
1030				)
1031			}
1032			statement := &Statement{
1033				ID:                  id,
1034				AccountID:           accountID,
1035				Currency:            currency,
1036				Period:              Period{Start: start, End: end},
1037				OpeningBalanceMinor: opening,
1038				ClosingBalanceMinor: closing,
1039				Lines:               []*StatementLine{},
1040				CreatedAt:           s.now(),
1041			}
1042			total := opening
1043			seen := map[string]bool{}
1044			for position, raw := range request.Lines {
1045				if raw == nil {
1046					return nil, ValidationError("lines[%d] must be an object", position+1)
1047				}
1048				field := fmt.Sprintf("lines[%d]", position+1)
1049				lineID, err := validateIdentifier(raw.ID, field+".id")
1050				if err != nil {
1051					return nil, err
1052				}
1053				if seen[lineID] {
1054					return nil, ValidationError("statement line id %s is duplicated", lineID)
1055				}
1056				seen[lineID] = true
1057				lineDate, err := validateDate(raw.Date, field+".date")
1058				if err != nil {
1059					return nil, err
1060				}
1061				if lineDate < start || lineDate > end {
1062					return nil, ValidationError("%s.date must fall inside the statement period", field)
1063				}
1064				amount, err := validateAmount(raw.AmountMinor, field+".amount_minor", false, true)
1065				if err != nil {
1066					return nil, err
1067				}
1068				reference, err := validateText(raw.Reference, field+".reference")
1069				if err != nil {
1070					return nil, err
1071				}
1072				description, err := validateText(raw.Description, field+".description")
1073				if err != nil {
1074					return nil, err
1075				}
1076				total += amount
1077				statement.Lines = append(statement.Lines, &StatementLine{
1078					ID:          lineID,
1079					Date:        lineDate,
1080					AmountMinor: amount,
1081					Reference:   reference,
1082					Description: description,
1083				})
1084			}
1085			if total != closing {
1086				return nil, ValidationError(
1087					"statement lines do not reconcile with the closing balance: opening %d plus lines %d is %d, not %d",
1088					opening, total-opening, total, closing,
1089				)
1090			}
1091			state.Statements[id] = statement
1092			return statement, nil
1093		})
1094	}
