	if err := json.Unmarshal(encoded, &decoded); err != nil {
		t.Fatalf("decode balance: %v", err)
	}
	if integer(t, decoded, "balance_minor") != 4200 || integer(t, decoded, "posting_count") != 1 {
		t.Fatalf("reopened balance is %v", decoded)
